css:
.statecraftsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1c2433;
    background: linear-gradient(160deg, #eef1f6 0%, #e4e8f1 100%);
    border-radius: 18px;
}

.statecraftsim-container * {
    box-sizing: border-box;
}

.statecraftsim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #11203d 0%, #1d3a63 55%, #2b4f87 100%);
    color: #f3f6fb;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(17, 32, 61, 0.32);
    border-bottom: 4px solid #c79a3a;
}

.statecraftsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.statecraftsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #f1d79a;
    background: rgba(199, 154, 58, 0.18);
    padding: 5px 14px;
    border-radius: 999px;
}

.statecraftsim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #d9e1ef;
}

.statecraftsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #25406b;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.statecraftsim-period-counter #currentDay,
.statecraftsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #11203d;
}

.statecraftsim-round-name {
    background: #d3ddee;
    color: #11203d;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.statecraftsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #8a5a13;
    background: #f6e9cb;
    padding: 4px 12px;
    border-radius: 999px;
}

.statecraftsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.statecraftsim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #d6deec;
    box-shadow: 0 4px 14px rgba(17, 32, 61, 0.07);
    border-top: 4px solid #2b4f87;
}

.statecraftsim-card-outcome { border-top-color: #1d6f5c; }
.statecraftsim-card-legit { border-top-color: #2b4f87; }
.statecraftsim-card-coalition { border-top-color: #6a4fb0; }
.statecraftsim-card-reputation { border-top-color: #c79a3a; }

.statecraftsim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #5e6b82;
}

.statecraftsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #11203d;
}

.statecraftsim-card-outcome .statecraftsim-value { color: #1d6f5c; }
.statecraftsim-card-legit .statecraftsim-value { color: #2b4f87; }
.statecraftsim-card-coalition .statecraftsim-value { color: #6a4fb0; }
.statecraftsim-card-reputation .statecraftsim-value { color: #b07f1c; }

.statecraftsim-sublabel {
    font-size: 0.76rem;
    color: #6f7c92;
    line-height: 1.35;
}

.statecraftsim-card-reputation.statecraftsim-rep-danger { border-top-color: #c0392b; }
.statecraftsim-card-reputation.statecraftsim-rep-danger .statecraftsim-value { color: #c0392b; }
.statecraftsim-card-outcome.statecraftsim-outcome-win { border-top-color: #1d6f5c; }
.statecraftsim-card-outcome.statecraftsim-outcome-win .statecraftsim-value { color: #14563f; }

.statecraftsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #11203d;
    color: #eaf0fa;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.statecraftsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #f1d79a;
}

.statecraftsim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #c79a3a;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(17, 32, 61, 0.06);
}

.statecraftsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.statecraftsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #11203d;
    margin-bottom: 6px;
}

.statecraftsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #2c3a52;
}

.statecraftsim-briefing-text strong { color: #1d6f5c; }
.statecraftsim-briefing-text em { color: #8a5a13; font-style: italic; }

.statecraftsim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #d6deec;
    box-shadow: 0 4px 14px rgba(17, 32, 61, 0.07);
}

.statecraftsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #11203d;
    border-bottom: 2px solid #e4e8f1;
    padding-bottom: 8px;
}

.statecraftsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #23344f;
    margin: 14px 0 6px;
}

.statecraftsim-container select,
.statecraftsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #bcc8de;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #f7f9fd;
    color: #1c2433;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.statecraftsim-container select:focus,
.statecraftsim-container input[type="number"]:focus {
    outline: none;
    border-color: #2b4f87;
    box-shadow: 0 0 0 3px rgba(43, 79, 135, 0.16);
}

.statecraftsim-container select option {
    background-color: #ffffff;
    color: #1c2433;
}

.statecraftsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #c79a3a;
}

.statecraftsim-range-readout,
.statecraftsim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #25406b;
    margin-top: 4px;
}

.statecraftsim-range-readout span:last-child,
.statecraftsim-alloc-readout span:nth-child(2) {
    color: #1d6f5c;
    font-weight: 800;
}

.statecraftsim-hint {
    font-size: 0.8rem;
    color: #6f7c92;
    margin-top: 4px;
    line-height: 1.4;
}

.statecraftsim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.statecraftsim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f2f5fb;
    border: 1px solid #dde4f0;
    border-radius: 9px;
    padding: 8px 12px;
}

.statecraftsim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #23344f;
}

.statecraftsim-alloc-row input[type="number"] {
    width: 96px;
    flex: 0 0 96px;
}

.statecraftsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.statecraftsim-container .btn-primary {
    background: linear-gradient(135deg, #1d3a63 0%, #2b4f87 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(29, 58, 99, 0.30);
}

.statecraftsim-container .btn-primary:hover {
    filter: brightness(1.10);
}

.statecraftsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #bcc8de;
    color: #5e6b82;
}

.statecraftsim-coach {
    background: #11203d;
    color: #eaf0fa;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(17, 32, 61, 0.24);
    border-left: 4px solid #c79a3a;
}

.statecraftsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #f1d79a;
    margin-bottom: 8px;
}

.statecraftsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.statecraftsim-coach-body strong { color: #f1d79a; }
.statecraftsim-coach-body em { color: #f6c9a8; font-style: italic; }

.statecraftsim-history,
.statecraftsim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #d6deec;
    box-shadow: 0 4px 14px rgba(17, 32, 61, 0.07);
}

.statecraftsim-history h3,
.statecraftsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #11203d;
}

.statecraftsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #23344f;
}

.statecraftsim-container table#usfHistoryTable th {
    background: #eaeef6;
    color: #11203d;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d4dcec;
}

.statecraftsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef2f8;
}

.statecraftsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f8fafd;
}

.statecraftsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .statecraftsim-container {
        padding: 14px;
    }
    .statecraftsim-header h1 {
        font-size: 1.7rem;
    }
    .statecraftsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .statecraftsim-value {
        font-size: 2rem;
    }
    .statecraftsim-clock {
        margin-left: 0;
    }
    .statecraftsim-period-counter {
        font-size: 0.88rem;
    }
    .statecraftsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .statecraftsim-alloc-row {
        flex-wrap: wrap;
    }
    .statecraftsim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .statecraftsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

